		root_hobt.CompletedMeetings,
		root_hobt.QuotedSiteVisits,
		root_hobt.CompletedSiteVisits,
                root_hobt.IsTotalHighlightRow
FROM	SJob.tvf_JobFeeDrawdown (	[[UserId]],
									''[[ParentGuid]]''
								) AS root_hobt' WHERE ID = 88

